CREATE TABLE IF NOT EXISTS records (kind VARCHAR(40) NOT NULL, id VARCHAR(64) NOT NULL, data LONGTEXT NOT NULL, PRIMARY KEY(kind,id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS credentials (id VARCHAR(64) PRIMARY KEY, ciphertext LONGTEXT NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS admins (name VARCHAR(100) PRIMARY KEY, password VARCHAR(255) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS jobs (id VARCHAR(32) PRIMARY KEY, resource VARCHAR(100) NOT NULL, kind VARCHAR(40) NOT NULL, payload LONGTEXT NOT NULL, status VARCHAR(30) NOT NULL, owner VARCHAR(32), lease BIGINT NOT NULL DEFAULT 0, attempts INTEGER NOT NULL DEFAULT 0, created BIGINT NOT NULL, result LONGTEXT NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS resource_locks (resource VARCHAR(100) PRIMARY KEY, operation VARCHAR(32) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS steps (id VARCHAR(32) PRIMARY KEY, operation VARCHAR(32) NOT NULL, at BIGINT NOT NULL, step VARCHAR(80) NOT NULL, data LONGTEXT NOT NULL) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS trongate_user_levels (id INTEGER PRIMARY KEY, level_title VARCHAR(100) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS trongate_users (id INTEGER PRIMARY KEY AUTO_INCREMENT, code VARCHAR(64) NOT NULL, user_level_id INTEGER NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS trongate_administrators (id INTEGER PRIMARY KEY AUTO_INCREMENT, username VARCHAR(100) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, trongate_user_id INTEGER NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS trongate_tokens (id INTEGER PRIMARY KEY AUTO_INCREMENT, token VARCHAR(64) NOT NULL UNIQUE, user_id INTEGER NOT NULL, expiry_date BIGINT NOT NULL, code VARCHAR(64)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS login_attempts (id INTEGER PRIMARY KEY AUTO_INCREMENT, target_table VARCHAR(100) NOT NULL, identifier VARCHAR(255) NOT NULL, ip_address VARCHAR(64) NOT NULL, attempted_at BIGINT NOT NULL) ENGINE=InnoDB;
INSERT INTO trongate_user_levels(id,level_title) SELECT 1,'Administrator' WHERE NOT EXISTS (SELECT 1 FROM trongate_user_levels WHERE id=1);
INSERT INTO trongate_user_levels(id,level_title) SELECT 2,'Team Member' WHERE NOT EXISTS (SELECT 1 FROM trongate_user_levels WHERE id=2);

CREATE TABLE IF NOT EXISTS team_members (id INTEGER PRIMARY KEY AUTO_INCREMENT, email VARCHAR(190) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, password VARCHAR(255) NOT NULL, trongate_user_id INTEGER NOT NULL UNIQUE, role VARCHAR(32) NOT NULL DEFAULT 'member', scope VARCHAR(32) NOT NULL DEFAULT 'scoped', permissions LONGTEXT NOT NULL, active TINYINT NOT NULL DEFAULT 1, created_at BIGINT NOT NULL, last_login BIGINT NOT NULL DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS team_invitations (id VARCHAR(32) PRIMARY KEY, email VARCHAR(190) NOT NULL, token_hash VARCHAR(64) NOT NULL UNIQUE, role VARCHAR(32) NOT NULL DEFAULT 'member', scope VARCHAR(32) NOT NULL DEFAULT 'scoped', permissions LONGTEXT NOT NULL, note VARCHAR(500) NOT NULL DEFAULT '', invited_by VARCHAR(190) NOT NULL DEFAULT '', created_at BIGINT NOT NULL, expires_at BIGINT NOT NULL, accepted_at BIGINT NOT NULL DEFAULT 0, revoked_at BIGINT NOT NULL DEFAULT 0, accepted_member_id INTEGER NOT NULL DEFAULT 0) ENGINE=InnoDB;
